-- ============================================================================
-- 檔案名稱: 04_submissions_05_24.sql
-- 責任描述: 示範種子資料 04 / 05：問卷 5~24 之 60 份回收、受訪者基本資料與逐題作答
-- 執行順序: schema.sql → seed/01 → 02 → 03 → 04 → 05 (完整重置)；
--           02 ~ 05 開頭會先刪除本檔負責之 ID 範圍，中途失敗時只需重跑該檔；本檔依賴 03 (題目與選項)
-- 執行方式: Spring Boot (spring.sql.init.data-locations 依序列出)、整合測試、E2E，或於 TiDB / MySQL 依序貼上執行
-- 邊界:     只用於初始化或重建示範環境；全部為單筆 INSERT，網頁版 SQL Editor 也能完整執行
-- 字元編碼: utf8mb4 / utf8mb4_unicode_ci
-- ============================================================================

USE `survey_flow`;

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
-- [Why]: 各檔之間有外鍵參照 (例如 04 的作答參照 03 的選項)，暫停外鍵檢查讓單一檔案可獨立重跑；檔尾恢復
SET FOREIGN_KEY_CHECKS = 0;

-- 先刪除本檔負責之資料範圍 (子表在前)，因此可單獨重跑而不產生重複
DELETE FROM `submission_answers` WHERE `id` BETWEEN 421 AND 880;
DELETE FROM `submission_basic_infos` WHERE `id` BETWEEN 41 AND 88;
DELETE FROM `submissions` WHERE `id` BETWEEN 41 AND 100;




-- 恢復外鍵檢查並提交
SET FOREIGN_KEY_CHECKS = 1;
COMMIT;
